SELECT CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, DATE_TRUNC('MONTH', o.order_date) AS order_month, COUNT(*) AS order_item_count FROM order_items oi INNER JOIN orders o ON oi.order_id = o.id GROUP BY CASE WHEN YEAR(o.order_date) < 2024 THEN 'before_2024' WHEN YEAR(o.order_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_TRUNC('MONTH', o.order_date) ORDER BY order_item_count DESC, order_cohort, order_month LIMIT 1;
